class Solution {
public:
    int maxLength(vector<int>& ribbons, int k) {
        int low = 1, high = 0;
        for (int r : ribbons) high = max(high, r);
        int ans = 0;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            long long total = 0;
            for (int r : ribbons) total += r / mid;
            if (total >= k) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int maxLength(int[] ribbons, int k) {
        int low = 1, high = 0;
        for (int r : ribbons) high = Math.max(high, r);
        int ans = 0;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            long total = 0;
            for (int r : ribbons) total += r / mid;
            if (total >= k) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}

/**
 * @param {number[]} ribbons
 * @param {number} k
 * @return {number}
 */
var maxLength = function(ribbons, k) {
    let low = 1, high = 0;
    for (const r of ribbons) if (r > high) high = r;
    let ans = 0;

    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        let total = 0;
        for (const r of ribbons) total += Math.floor(r / mid);
        if (total >= k) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
};
